import { getPracticeProblems as getAllDocPracticeProblems } from './contentTree';

/**
 * The structured execution and learning metadata behind practice problems --
 * separate from MDX content on purpose.
 */

export interface PracticeTestCase {
  id: string;
  label: string;
  input: Record<string, unknown>;
  expectedOutput?: unknown;
  expectError?: string;
  hidden?: boolean;
  description?: string;
}

export interface ConceptConnection {
  title: string;
  route: string;
  description: string;
}

export interface RuntimeCapabilities {
  language: 'python';
  capabilities: Array<'python' | 'numpy' | 'pytorch' | 'gpu'>;
}

export type CanvasNodeType = 'reasoner' | 'tool' | 'memory' | 'database' | 'final_answer';

export interface CanvasComponentDefinition {
  type: CanvasNodeType;
  label: string;
  role: string;
  description: string;
  badge?: string;
  icon?: string;
  isHub?: boolean;
}

export interface CanvasInitialNode {
  id: string;
  type: CanvasNodeType;
  label: string;
  position: { x: number; y: number };
  role?: string;
  description?: string;
}

export interface CanvasInitialEdge {
  id: string;
  source: string;
  target: string;
  label?: string;
}

export interface CanvasSpec {
  title: string;
  description: string;
  availableComponents: CanvasComponentDefinition[];
  initialNodes: CanvasInitialNode[];
  initialEdges?: CanvasInitialEdge[];
}

export interface GuidedStep {
  title: string;
  prompt: string;
  code: string;
  starterSnippet?: string;
  explanation?: string;
}

export interface FrameworkGap {
  id: string;
  title: string;
  description: string;
  hint?: string;
  starterSnippet: string;
  solutionSnippet: string;
}

export interface FrameworkSpec {
  framework: 'langgraph';
  title: string;
  subtitle: string;
  disclaimer: string;
  functionName: string;
  starterCode: string;
  solutionCode: string;
  gaps: FrameworkGap[];
  testCases: PracticeTestCase[];
}

export interface PracticeProblem {
  id: string;
  title: string;
  difficulty: 'easy' | 'medium' | 'hard';
  topic: string;
  estimatedTime: string;
  functionName: string;
  functionSignature: string;
  starterCode: string;
  mission: string;
  taskDescription: string;
  constraints: string[];
  testCases: PracticeTestCase[];
  libraryPolicyText?: string;
  bonusPoints?: number;
  bonusDescription?: string;
  hints?: {
    small: string;
    strong: string;
    concept: string;
  };
  conceptConnections?: ConceptConnection[];
  runtime: RuntimeCapabilities;
  /** Controls judging engine: 'local' (Pyodide in-browser), 'server' (Sandboxed server), or 'hybrid' (Server with Pyodide fallback) */
  judgeMode?: 'local' | 'server' | 'hybrid';
  prerequisite?: string | null;
  stage?: string;
  stageNumber?: number;
  points?: number;
  canvasSpec?: CanvasSpec;
  guidedSteps?: GuidedStep[];
  frameworkSpec?: FrameworkSpec;
}

