        input: {"events": [{"tick": 1, "heartbeats": {"node-1": 10, "node-2": 5}}, {"tick": 5, "heartbeats": {"node-1": 14, "node-2": 9}}], "suspect_timeout": 5, "dead_timeout": 10},
        expectedOutput: {"node-1": "ALIVE", "node-2": "ALIVE"},
