    hints: {
      small: "Check len(new_key) == len(new_value) and check against cached_keys[0] if cached_keys is non-empty.",
      strong: "If window_size is not None and len(keys) > window_size, evicted_count is len(keys) - window_size and keys = keys[-window_size:].",
      concept: "Sliding window attention bounds KV cache memory to O(W) rather than O(N), critical for long-running streaming inference.",
    },
