  'llm-app-prob-14': {
    id: 'llm-app-prob-14',
    title: "Exponential Backoff Schedule Calculator",
    difficulty: 'medium',
    topic: 'LLM Application Engineering',
    estimatedTime: '20–25 min',
    functionName: 'compute_backoff_schedule',
    functionSignature: "compute_backoff_schedule(max_retries: int, base_delay_ms: int = 500, max_delay_ms: int = 10000, factor: float = 2.0, jitter_fractions: list[float] | None = None) -> dict",
    starterCode: "def compute_backoff_schedule(max_retries: int, base_delay_ms: int = 500, max_delay_ms: int = 10000, factor: float = 2.0, jitter_fractions: list[float] | None = None) -> dict:\n    \"\"\"Calculate exponential backoff retry intervals with jitter and maximum delay clamping.\n    \n    Args:\n        max_retries: Number of retry attempts.\n        base_delay_ms: Initial backoff delay in milliseconds.\n        max_delay_ms: Upper bound for any single retry delay.\n        factor: Exponential multiplier base.\n        jitter_fractions: Optional list of fractional jitter adjustments per attempt.\n    Returns:\n        Dict with 'delays_ms', 'total_wait_ms', and 'max_retries'.\n    \"\"\"\n    # Your implementation here\n    pass\n",
    mission: "Calculate deterministic retry backoff intervals with jitter multipliers and latency ceilings for robust API client calls.",
    taskDescription: "Implement `compute_backoff_schedule(max_retries, base_delay_ms=500, max_delay_ms=10000, factor=2.0, jitter_fractions=None)`. For each attempt `k` in `0..max_retries-1`, calculate raw delay as `min(max_delay_ms, base_delay_ms * (factor ** k))`. If `jitter_fractions` is provided, multiply raw delay by `(1.0 + jitter_fractions[k])` and cast to `int`. Return `{'delays_ms': delays, 'total_wait_ms': sum(delays), 'max_retries': max_retries}`. Raise `ValueError` if `max_retries < 0` or `base_delay_ms <= 0`.",
    libraryPolicyText: "Libraries allowed · Pure Python earns +10 bonus XP",
    bonusPoints: 10,
    bonusDescription: "Pure Python earns +10 Bonus XP.",
    constraints: ["Clamp raw delays at max_delay_ms before applying jitter.", "Cast all computed delay values to integer milliseconds.", "Raise ValueError on non-positive base_delay_ms or negative max_retries."],
    hints: {
      small: "Calculate float raw delay with pow(factor, k) and min(max_delay_ms, raw).",
      strong: "Apply jitter index safely: use jitter_fractions[k] if k < len(jitter_fractions) else 0.0.",
      concept: "Exponential backoff prevents thundering herd congestion when LLM services experience transient load.",
    },
    conceptConnections: [
      { title: "Provider Fallback", route: "/practice/llm-app-prob-12", description: "Failing over across providers" },
      { title: "Rate Limiter", route: "/practice/llm-app-prob-25", description: "Sliding window rate limiting" },
    ],
    testCases: [
      { id: "tc1", label: "Standard exponential progression without jitter", input: {"max_retries": 4, "base_delay_ms": 500, "max_delay_ms": 10000, "factor": 2.0, "jitter_fractions": null}, expectedOutput: {"delays_ms": [500, 1000, 2000, 4000], "total_wait_ms": 7500, "max_retries": 4}, hidden: false },
      { id: "tc2", label: "Backoff clamped by max delay", input: {"max_retries": 5, "base_delay_ms": 1000, "max_delay_ms": 3000, "factor": 2.0, "jitter_fractions": null}, expectedOutput: {"delays_ms": [1000, 2000, 3000, 3000, 3000], "total_wait_ms": 12000, "max_retries": 5}, hidden: false },
      { id: "tc3", label: "Backoff with positive jitter adjustments", input: {"max_retries": 3, "base_delay_ms": 100, "max_delay_ms": 1000, "factor": 2.0, "jitter_fractions": [0.1, 0.2, 0.15]}, expectedOutput: {"delays_ms": [110, 240, 459], "total_wait_ms": 809, "max_retries": 3}, hidden: false },
      { id: "tc4", label: "Invalid base delay raises ValueError", input: {"max_retries": 2, "base_delay_ms": -50}, expectError: 'ValueError', hidden: false },
      { id: "tc5", label: "Zero retries produces empty schedule", input: {"max_retries": 0, "base_delay_ms": 500}, expectedOutput: {"delays_ms": [], "total_wait_ms": 0, "max_retries": 0}, hidden: true },
    ],
    runtime: { language: 'python', capabilities: ['python'] },
  },

